1	package com.fream.back.domain.payment.service.kafka;
2	
3	import com.fream.back.domain.order.entity.Order;
4	import com.fream.back.domain.order.repository.OrderRepository;
5	import com.fream.back.domain.payment.dto.kafka.PaymentEvent;
6	import com.fream.back.domain.payment.entity.Payment;
7	import com.fream.back.domain.payment.exception.PaymentException;
8	import com.fream.back.domain.payment.repository.PaymentRepository;
9	import com.fream.back.domain.payment.service.command.PaymentCommandService;
10	import com.fream.back.domain.user.entity.User;
11	import com.fream.back.domain.user.service.query.UserQueryService;
12	import lombok.RequiredArgsConstructor;
13	import lombok.extern.slf4j.Slf4j;
14	import org.springframework.kafka.annotation.KafkaListener;
15	import org.springframework.kafka.support.Acknowledgment;
16	import org.springframework.kafka.support.KafkaHeaders;
17	import org.springframework.messaging.handler.annotation.Header;
18	import org.springframework.messaging.handler.annotation.Payload;
19	import org.springframework.stereotype.Service;
20	import org.springframework.transaction.annotation.Transactional;
21	
22	import java.time.Duration;
23	import java.time.Instant;
24	import java.util.Optional;
25	
26	/**
27	 * 결제 이벤트 컨슈머
28	 * Kafka로부터 결제 처리 이벤트를 수신하여 실제 결제 처리 수행
29	 */
30	@Service
31	@RequiredArgsConstructor
32	@Slf4j
33	public class PaymentEventConsumer {
34	
35	    private final PaymentCommandService paymentCommandService;
36	    private final PaymentEventProducer paymentEventProducer;
37	    private final OrderRepository orderRepository;
38	    private final PaymentRepository paymentRepository;
39	    private final UserQueryService userQueryService;
40	
41	    /**
42	     * 결제 처리 이벤트 리스너
43	     * 멱등성을 보장하여 중복 결제를 방지
44	     */
45	    @KafkaListener(
46	            topics = "payment-processing-topic",
47	            groupId = "payment-processing-group",
48	            containerFactory = "paymentEventKafkaListenerContainerFactory"
49	    )
50	    @Transactional
51	    public void handlePaymentEvent(
52	            @Payload PaymentEvent event,
53	            @Header(KafkaHeaders.RECEIVED_PARTITION) int partition,
54	            @Header(KafkaHeaders.OFFSET) long offset,
55	            Acknowledgment acknowledgment) {
56	
57	        Instant start = Instant.now();
58	
59	        try {
60	            log.info("결제 처리 이벤트 수신: 주문ID={}, 이벤트ID={}, 파티션={}, 오프셋={}",
61	                    event.getOrderId(), event.getEventId(), partition, offset);
62	
63	            // 1. 멱등성 검사 - 이미 처리된 주문인지 확인
64	            if (isPaymentAlreadyProcessed(event.getOrderId())) {
65	                log.warn("이미 처리된 결제 요청 - 중복 처리 방지: 주문ID={}", event.getOrderId());
66	                acknowledgment.acknowledge();
67	                return;
68	            }
69	
70	            // 2. 주문 정보 조회
71	            Order order = orderRepository.findById(event.getOrderId())
72	                    .orElseThrow(() -> new IllegalArgumentException(
73	                            "주문을 찾을 수 없습니다. 주문ID: " + event.getOrderId()));
74	
75	            // 3. 사용자 정보 조회
76	            User user = userQueryService.findByEmail(event.getUserEmail());
77	
78	            // 4. 주문과 사용자 일치 여부 확인
79	            if (!order.getUser().getId().equals(user.getId())) {
80	                log.error("주문과 사용자 정보 불일치: 주문ID={}, 주문사용자ID={}, 요청사용자ID={}",
81	                        event.getOrderId(), order.getUser().getId(), user.getId());
82	                throw new PaymentException(null, "주문과 사용자 정보가 일치하지 않습니다.");
83	            }
84	
85	            // 5. 결제 처리 수행
86	            Payment payment = paymentCommandService.processPayment(order, user, event.getPaymentRequest());
87	
88	            log.info("결제 처리 완료: 주문ID={}, 결제ID={}, 결제상태={}",
89	                    event.getOrderId(), payment.getId(), payment.getStatus());
90	
91	            // 6. 처리 완료 ACK
92	            acknowledgment.acknowledge();
93	
94	            // 처리 시간 로깅
95	            Instant end = Instant.now();
96	            Duration duration = Duration.between(start, end);
97	            log.info("결제 처리 완료 - 소요시간: {}ms, 주문ID={}", duration.toMillis(), event.getOrderId());
98	
99	        } catch (PaymentException e) {
100	            log.error("결제 처리 실패 (PaymentException): 주문ID={}, 오류={}",
101	                    event.getOrderId(), e.getMessage(), e);
102	            handlePaymentFailure(event, e, acknowledgment);
103	
104	        } catch (Exception e) {
105	            log.error("결제 처리 중 예상치 못한 오류: 주문ID={}, 오류={}",
106	                    event.getOrderId(), e.getMessage(), e);
107	            handlePaymentFailure(event, e, acknowledgment);
108	        }
109	    }
110	
111	    /**
112	     * 결제 재시도 이벤트 리스너
113	     */
114	    @KafkaListener(
115	            topics = "payment-retry-topic",
116	            groupId = "payment-retry-group",
117	            containerFactory = "paymentEventKafkaListenerContainerFactory"
118	    )
119	    @Transactional
120	    public void handlePaymentRetryEvent(
121	            @Payload PaymentEvent event,
122	            Acknowledgment acknowledgment) {
123	
124	        try {
125	            log.info("결제 재시도 처리: 주문ID={}, 재시도횟수={}",
126	                    event.getOrderId(), event.getRetryCount());
127	
128	            // 재시도 횟수 확인
129	            if (event.isMaxRetryExceeded()) {
130	                log.error("최대 재시도 횟수 초과: 주문ID={}, 재시도횟수={}",
131	                        event.getOrderId(), event.getRetryCount());
132	                acknowledgment.acknowledge();
133	                return;
134	            }
135	
136	            // 멱등성 재확인
137	            if (isPaymentAlreadyProcessed(event.getOrderId())) {
138	                log.info("재시도 중 결제 완료 확인: 주문ID={}", event.getOrderId());
139	                acknowledgment.acknowledge();
140	                return;
141	            }
142	
143	            // 재시도 지연 (백오프 전략)
144	            Thread.sleep(Math.min(1000 * event.getRetryCount(), 5000));
145	
146	            // 결제 재처리
147	            handlePaymentEvent(event, 0, 0, acknowledgment);
148	
149	        } catch (InterruptedException e) {
150	            Thread.currentThread().interrupt();
151	            log.error("결제 재시도 중 인터럽트 발생: 주문ID={}", event.getOrderId());
152	            acknowledgment.acknowledge();
153	        } catch (Exception e) {
154	            log.error("결제 재시도 처리 중 오류: 주문ID={}, 오류={}",
155	                    event.getOrderId(), e.getMessage(), e);
156	            acknowledgment.acknowledge();
157	        }
158	    }
159	
160	    /**
161	     * 결제가 이미 처리되었는지 확인 (멱등성 보장)
162	     */
163	    private boolean isPaymentAlreadyProcessed(Long orderId) {
164	        try {
165	            Optional<Payment> existingPayment = paymentRepository.findByOrder_Id(orderId);
166	
167	            if (existingPayment.isPresent()) {
168	                Payment payment = existingPayment.get();
169	                log.info("기존 결제 발견: 주문ID={}, 결제ID={}, 결제상태={}",
170	                        orderId, payment.getId(), payment.getStatus());
171	
172	                // 성공한 결제가 있으면 중복 처리로 간주
173	                return payment.isSuccess();
174	            }
175	
176	            return false;
177	        } catch (Exception e) {
178	            log.error("결제 중복 검사 중 오류 발생: 주문ID={}, 오류={}", orderId, e.getMessage(), e);
179	            return false;
180	        }
181	    }
182	
183	    /**
184	     * 결제 실패 처리
185	     */
186	    private void handlePaymentFailure(PaymentEvent event, Exception error, Acknowledgment acknowledgment) {
187	        try {
188	            // 재시도 가능한 오류인지 판단
189	            if (isRetryableError(error)) {
190	                log.info("재시도 가능한 오류로 재시도 이벤트 발행: 주문ID={}", event.getOrderId());
191	                paymentEventProducer.sendPaymentRetryEvent(event);
192	            } else {
193	                log.error("재시도 불가능한 오류로 결제 실패 처리: 주문ID={}, 오류={}",
194	                        event.getOrderId(), error.getMessage());
195	                // TODO: 결제 실패 알림 등 추가 처리
196	            }
197	
198	            acknowledgment.acknowledge();
199	
200	        } catch (Exception e) {
201	            log.error("결제 실패 처리 중 오류: 주문ID={}, 오류={}", event.getOrderId(), e.getMessage(), e);
202	            acknowledgment.acknowledge();
203	        }
204	    }
205	
206	    /**
207	     * 재시도 가능한 오류인지 판단
208	     */
209	    private boolean isRetryableError(Exception error) {
210	        // 네트워크 오류, 일시적인 시스템 오류 등은 재시도 가능
211	        return !(error instanceof IllegalArgumentException) &&
212	                !(error.getMessage() != null && error.getMessage().contains("찾을 수 없습니다"));
213	    }
214	}

